<script setup lang="ts">
import {useRoute} from 'vue-router';
import LeakPanel from "./components/LeakPanel.vue";
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {usePipelineStore} from '../../store/usePipelineStore';import {useRealtimeStore} from '../../store/useRealtimeStore';import {pipelineApi} from '../../api/pipelines';import type {PipelineType} from '../../types/pipeline';import {parkContext} from '../../config/park';
import DigitalTwinScene from '../../components/digital-twin/DigitalTwinScene.vue';
import PipelineList from './components/PipelineList.vue';import PipelineDetail from './components/PipelineDetail.vue';import PipelineTracePanel from './components/PipelineTracePanel.vue';import PipelineTopologyGraph from './components/PipelineTopologyGraph.vue';import IsolationOptions from './components/IsolationOptions.vue';import ValveCard from './components/ValveCard.vue';import './pipeline.css';
const store=usePipelineStore(),realtime=useRealtimeStore(),route=useRoute();const leakMode=ref(route.query.mode==='leak'||!!realtime.state?.leak?.scenarioId);
watch(()=>route.query.mode,mode=>{if(mode==='leak')leakMode.value=true;});
watch(()=>realtime.state?.leak?.scenarioId,id=>{if(id)leakMode.value=true;});
const category=ref(''),types=ref<PipelineType[]>(['water','drainage','fire']),focusNode=ref(''),busy=ref(false),nearest=ref({upstream:[] as string[],downstream:[] as string[]});
const request=new AbortController();let alive=true,lookup=0;
const asset=computed(()=>store.assets.edges.find(e=>e.id===store.selectedPipeline));
const states=computed(()=>realtime.state?.pipelines??[]);
const live=computed(()=>states.value.find(e=>e.id===store.selectedPipeline));
const valves=computed(()=>store.assets.valves.map(v=>({...v,...realtime.state?.valves?.find(s=>s.id===v.id)})));
const normalRate=computed(()=>store.assets.edges.length?Math.round(store.assets.edges.filter(e=>(states.value.find(s=>s.id===e.id)?.status??e.status)==='normal').length/store.assets.edges.length*100):0);
function select(id:string){focusNode.value='';store.select(id);}
function selectNode(id:string){focusNode.value=id;if(store.assets.valves.some(v=>v.nodeId===id))store.selectedValve=id;}
function categoryChange(value:string){category.value=value;types.value=value&&value!=='valves'?[value as PipelineType]:['water','drainage','fire'];}
async function relation(){const n=++lookup;try{const result=await pipelineApi.valves(store.selectedPipeline);if(alive&&n===lookup)nearest.value=result;}catch{if(alive&&n===lookup)nearest.value={upstream:[],downstream:[]};}}
async function control(id:string,status:'open'|'closed'){busy.value=true;try{const data=await pipelineApi.control(id,status);if(!alive)return;store.clear();store.affectedBuildings=data.affectedBuildings;store.traceEdges=data.state.pipelines.filter(p=>p.status==='isolated').map(p=>p.id);store.affectedTrace=true;await relation();}catch{store.error='阀门控制失败，请检查开发模式和数据库连接。';}finally{busy.value=false;}}
watch(()=>store.selectedPipeline,relation);watch(()=>realtime.state?.valves?.map(v=>v.status).join(','),()=>void relation());
onMounted(async()=>{await store.load(request.signal);if(alive)void relation();});onBeforeUnmount(()=>{alive=false;lookup++;request.abort();store.clear();});
</script>
<template><div class="section-heading"><div><span class="eyebrow">CAOHEJING TECH OASIS · UNDERGROUND TWIN</span><h2>地下管网与空间孪生中心</h2><p>{{parkContext.name}}公开地上 GIS 的软件仿真管网映射</p></div><span>软件示范管网 · 非真实园区地下管网</span></div><div v-if="store.error" role="alert">{{store.error}}</div><div class="pipeline-stats panel"><span>管网总长<strong>{{(store.assets.edges.reduce((n,e)=>n+e.length,0)/1000).toFixed(2)}} <small>km</small></strong></span><span>管段数量<strong>{{store.assets.edges.length}}</strong></span><span>阀门数量<strong>{{store.assets.valves.length}}</strong></span><span>正常率<strong>{{normalRate}}%</strong></span><span class="pipeline-source">资产入库 / 拓扑计算 / 实时仿真</span></div><p v-if="store.loading">正在加载管网资产…</p><div class="leak-controls pipeline-mode-switch" role="group" aria-label="管网查看模式"><button :aria-pressed="!leakMode" @click="leakMode=false">正常模式</button><button :aria-pressed="leakMode" @click="leakMode=true">泄漏事故模式</button><span>{{leakMode?'异常观测 → 疑似定位 → 拓扑影响 → 人工隔离':'资产与实时状态 → 上下游追踪 → 隔离预览'}}</span></div><LeakPanel v-if="leakMode"/><template v-else><div class="pipeline-layout"><PipelineList :assets="store.assets.edges" :states="states" :selected="store.selectedPipeline" :category="category" :valves="valves" @valve="selectNode" @select="select" @category="categoryChange"/><div class="pipeline-center"><div class="pipeline-filters"><label v-for="(name,key) in {water:'给水',drainage:'排水',fire:'消防'}" :key="key"><input type="checkbox" v-model="types" :value="key"/>{{name}}</label></div><DigitalTwinScene v-if="store.assets.edges.length" :realtime-state="realtime.state" :pipeline-network="store.assets" :focus-pipeline-id="store.selectedPipeline" :focus-node-id="focusNode" :pipeline-types="types" :trace-edges="store.traceEdges" :affected-trace="store.affectedTrace" initial-underground @pipeline-select="select" @valve-select="selectNode"/><PipelineTracePanel :trace="store.trace" :buildings="store.affectedBuildings" @analyze="store.analyze" @clear="store.clear"/></div><div class="pipeline-right"><PipelineDetail :asset="asset" :state="live"/><ValveCard :valves="valves" :selected="store.selectedValve" :nearest="nearest" :busy="busy" @select="selectNode" @control="control"/></div></div><PipelineTopologyGraph :network="store.topology" :types="types" :selected="store.selectedPipeline" :trace="store.traceEdges" @edge="select" @node="selectNode"/><IsolationOptions :options="store.isolationOptions" @preview="store.preview"/></template></template>
